"use client";
import {ArtemisScope} from "./artemis-scope";
import type { ArtemisCtaContent } from "./components/cta-sections/content";
import View5 from "./components/cta-sections/variants/06-shade-panel";
const views={"shade-panel":View5};
export type { ArtemisCtaContent, ArtemisCtaImage, ArtemisCtaLink, ArtemisCtaQuestion, ArtemisCtaStat } from "./components/cta-sections/content";
export interface ArtemisCtaSectionsProps{className?:string;variant?:"shade-panel"; /** The words on the CTA section; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisCtaContent>; }
export function ArtemisCtaSections({className,variant="shade-panel",content}:ArtemisCtaSectionsProps){const View=views[variant];return <ArtemisScope className={className}><View content={content}/></ArtemisScope>;}

// @zeus-internal

/** The words on a button or link, and where it goes. */
export interface ArtemisCtaLink {
  label: string;
  href: string;
}

/** A picture, and the words that describe it. */
export interface ArtemisCtaImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** A figure with a short label under it. */
export interface ArtemisCtaStat {
  /** The figure as text, such as "120" or "4.9". Its digits roll into place. */
  value: string;
  /** Shown right after the figure, such as "K+" or "/5". */
  suffix?: string;
  /** What the figure counts. */
  label: string;
}

/** A question and its answer. */
export interface ArtemisCtaQuestion {
  question: string;
  answer: string;
  /** A short id, unique in the list, used in the row's element ids. Defaults to the row's position. */
  id?: string;
}

/** The words on an Artemis CTA section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisCtaContent {
  /** The short line above the heading. sunflower, product-window, proof-orbit, shade-panel, glow and terminal. */
  badge?: string;
  /** The heading. All layouts. */
  headline: string;
  /** The heading's second part. glow shows it on a line of its own in a muted tone; faq, terminal and split start a new line for it; the other layouts run it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** The paragraph under the heading. All layouts. */
  subhead: string;
  /** The main button. All layouts. */
  cta: ArtemisCtaLink;
  /** A second button. floating-gallery, portrait-frame, glow, terminal and split. */
  secondaryCta?: ArtemisCtaLink;
  /** A quiet text link under the buttons. split. */
  link?: ArtemisCtaLink;
  /** A short line near the buttons. sunflower, portrait-frame, proof-orbit and glow. */
  note?: string;
  /** The picture beside the words. portrait-frame, which also blurs it behind the panel, and glow. */
  image?: ArtemisCtaImage;
  /** Photos floating at the sides. floating-gallery: up to six, in pairs from the top, left then right; under 768px wide only the first two show. */
  images?: ArtemisCtaImage[];
  /** Faces in a row above the words. proof-orbit: up to five, from the left; the third is the largest. */
  avatars?: ArtemisCtaImage[];
  /** What the row of faces shows, read by screen readers. proof-orbit. Left out, it keeps the layout's own only when `avatars` is left out too. */
  avatarsLabel?: string;
  /** Figures under the buttons. floating-gallery; four look best. */
  stats?: ArtemisCtaStat[];
  /** Short facts along the foot of the panel. glow. */
  highlights?: string[];
  /** An install command with a copy button. terminal types it out; split shows it on its button. */
  command?: string;
  /** The lines the terminal prints after `command`. terminal. Left out, it keeps the layout's own lines only when `command` is left out too. */
  commandOutput?: string[];
  /** Questions with answers that open one at a time; the first starts open. faq. */
  questions?: ArtemisCtaQuestion[];
}

"use client";
// @zeus-internal
import {useArtemisReduceAfterHydration} from "../../../lib/use-reduce-after-hydration";
import { MotionConfig, motion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisCtaContent } from "../content";
const DEFAULT = {
    badge: "Built for the decisive moment",
    headline: "Turn attention into a clear next step.",
    subhead: "A focused close for launches, waitlists, and products that are ready to move.",
    cta: { label: "Start the next chapter", href: "#" },
} satisfies ArtemisCtaContent;
const IN_VIEW = { once: true } as const;
const INSTANT = { duration: 0 } as const;
const COLUMNS = [
    "art:bg-[radial-gradient(circle_at_20%_46%,rgba(72,99,188,0.3),rgba(15,23,58,0.12)_72%)]",
    "art:bg-[linear-gradient(180deg,rgba(22,34,80,0.42),rgba(7,12,34,0.3))]",
    "art:bg-[radial-gradient(circle_at_50%_42%,rgba(52,76,154,0.28),rgba(12,19,49,0.22)_76%)]",
    "art:bg-[linear-gradient(180deg,rgba(13,22,57,0.32),rgba(7,11,31,0.38))]",
    "art:bg-[radial-gradient(circle_at_45%_46%,rgba(62,88,172,0.3),rgba(12,19,48,0.2)_74%)]",
    "art:bg-[linear-gradient(180deg,rgba(15,24,62,0.42),rgba(7,11,31,0.32))]",
] as const;
const COLUMN_HIDDEN = { opacity: 0, scaleY: 1.05 };
const COLUMN_SHOWN = { opacity: 1, scaleY: 1 };
function reveal(y: number, duration: number, delay: number, blur?: number) {
    return {
        initial: blur === undefined ? { opacity: 0, y } : { opacity: 0, y, filter: `blur(${blur}px)` },
        whileInView: blur === undefined ? { opacity: 1, y: 0 } : { opacity: 1, y: 0, filter: "blur(0px)" },
        viewport: IN_VIEW,
        transition: { duration, delay, ease: ARTEMIS_EASE_OUT },
    };
}
const EYEBROW = reveal(10, 0.55, 0);
const HEADING = reveal(18, 0.7, 0.08, 7);
const BODY = reveal(12, 0.6, 0.16);
const ACTION = reveal(12, 0.6, 0.24);
export default function CtaSectionsShadePanel({ content }: { content?: Partial<ArtemisCtaContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const reduce = useArtemisReduceAfterHydration();
    const hover = reduce ? undefined : { scale: 1.01 };
    const tap = reduce ? undefined : { scale: 0.99 };
    return (<MotionConfig reducedMotion="user">
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
          <div data-artemis-theme="dark" className="art:relative art:mx-auto art:min-h-[32rem] art:w-full art:max-w-6xl art:overflow-hidden art:rounded-2xl art:bg-[#10183c]">
            <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:grid art:grid-cols-6">
              {COLUMNS.map((bg, i) => (<motion.div key={bg} className={`art:origin-bottom ${bg}`} initial={COLUMN_HIDDEN} whileInView={COLUMN_SHOWN} viewport={IN_VIEW} transition={reduce ? INSTANT : { duration: 0.9, delay: i * 0.06, ease: ARTEMIS_EASE_OUT }}/>))}
            </div>
            <div aria-hidden="true" className="art:pointer-events-none art:absolute art:inset-0 art:bg-[radial-gradient(circle_at_14%_38%,rgba(83,113,211,0.22),transparent_34%),linear-gradient(90deg,rgba(5,9,29,0.04),rgba(5,9,29,0.22))]"/>
            <div className="art:relative art:flex art:min-h-[32rem] art:items-center art:px-7 art:py-20 art:@min-[640px]/artemis:px-12 art:@min-[1024px]/artemis:px-20">
              <div className="art:max-w-xl art:text-left">
                <motion.p className="art:font-medium art:text-muted-foreground art:text-xs art:uppercase art:tracking-widest" {...EYEBROW} transition={reduce ? INSTANT : EYEBROW.transition}>
                  {copy.badge}
                </motion.p>
                <motion.h2 className="art:mt-6 art:max-w-lg art:text-pretty art:text-4xl art:font-medium art:text-foreground art:leading-tight art:tracking-tight" {...HEADING} transition={reduce ? INSTANT : HEADING.transition}>
                  {copy.headlineAccent ? `${copy.headline} ${copy.headlineAccent}` : copy.headline}
                </motion.h2>
                <motion.p className="art:mt-5 art:max-w-md art:text-pretty art:text-base art:text-muted-foreground art:leading-7" {...BODY} transition={reduce ? INSTANT : BODY.transition}>
                  {copy.subhead}
                </motion.p>
                <motion.div className="art:mt-8" {...ACTION} transition={reduce ? INSTANT : ACTION.transition}>
                  <motion.a whileHover={hover} whileTap={tap} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-9 art:rounded-full" href={copy.cta.href} tabIndex={0}>
                    {copy.cta.label}
                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-right art:size-4" aria-hidden="true">
                      <path d="M5 12h14"/>
                      <path d="m12 5 7 7-7 7"/>
                    </svg>
                  </motion.a>
                </motion.div>
              </div>
            </div>
          </div>
        </section>
      </div>
    </MotionConfig>);
}
